-- Create "users" table
CREATE TABLE "users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "username" character varying NOT NULL,
  "display_name" character varying NOT NULL,
  "is_admin" boolean NOT NULL DEFAULT false,
  "email" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
-- Create index "users_username_key" to table: "users"
CREATE UNIQUE INDEX "users_username_key" ON "users" ("username");
-- Create "accounts" table
CREATE TABLE "accounts" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "provider" character varying NOT NULL,
  "password" character varying NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "user_accounts" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "accounts_users_accounts" FOREIGN KEY ("user_accounts") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "account_user_accounts" to table: "accounts"
CREATE INDEX "account_user_accounts" ON "accounts" ("user_accounts");
-- Create "issues" table
CREATE TABLE "issues" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "title" character varying NOT NULL,
  "description" character varying NOT NULL,
  "status" character varying NOT NULL DEFAULT 'open',
  "upvotes" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "user_id" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "issues_users_issues" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create index "issue_user_id" to table: "issues"
CREATE INDEX "issue_user_id" ON "issues" ("user_id");
-- Create "files" table
CREATE TABLE "files" (
  "id" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "issue_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "files_issues_issue" FOREIGN KEY ("issue_id") REFERENCES "issues" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "file_issue_id" to table: "files"
CREATE INDEX "file_issue_id" ON "files" ("issue_id");
-- Create "upvotes" table
CREATE TABLE "upvotes" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "issue_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "upvotes_issues_issue" FOREIGN KEY ("issue_id") REFERENCES "issues" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "upvote_issue_id" to table: "upvotes"
CREATE INDEX "upvote_issue_id" ON "upvotes" ("issue_id");
-- Create index "upvote_user_id_issue_id" to table: "upvotes"
CREATE UNIQUE INDEX "upvote_user_id_issue_id" ON "upvotes" ("user_id", "issue_id");
